function sloganGenerate(name, keywords, rng){
  name=String(name||'').trim(); if(!name) return {error:'请填写品牌/产品名'};
  rng=rng||Math.random;
  var kws=String(keywords||'').split(/[,，\s]+/).filter(function(s){return s;});
  var kw = kws.length? kws[Math.floor(rng()*kws.length)] : '品质';
  var tpl=[
    name+'，'+kw+'的新选择',
    '选'+name+'，'+kw+'更出众',
    '遇见'+name+'，'+kw+'如此简单',
    name+' · 让'+kw+'更进一步',
    '因为'+name+'，'+kw+'更美好',
    '爱上'+name+'，从'+kw+'开始',
    name+'：'+kw+'与匠心兼得'
  ];
  var n=Math.min(5, tpl.length); var out=[]; var used={};
  while(out.length<n){ var i=Math.floor(rng()*tpl.length); if(!used[i]){used[i]=1; out.push(tpl[i]);} }
  return {slogans:out, keyword:kw};
}
var EXPORTS={sloganGenerate:sloganGenerate};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SloganForgePure = EXPORTS; }
